import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE='http://localhost:8080'
token=None

def get_token():
    global token
    while True:
        try:
            req=urllib.request.Request(BASE+'/token', method='POST')
            with urllib.request.urlopen(req, timeout=10) as r:
                token=[REDACTED_SECRET]'token']; return
        except urllib.error.HTTPError as e:
            wait=float(e.headers.get('Retry-After','1')); time.sleep(wait)
        except Exception:
            time.sleep(1)

def fetch(path):
    global token
    if token is None: get_token()
    while True:
        req=urllib.request.Request(BASE+path, headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req, timeout=10) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            if e.code in (401,403):
                get_token(); continue
            if e.code==429:
                raw=e.headers.get('Retry-After')
                if raw is None:
                    try: raw=json.load(e)['retry_after']
                    except Exception: raw='1'
                time.sleep(float(raw)); continue
            time.sleep(1)
        except Exception:
            time.sleep(1)

orders=[]; seen={}; path='/orders?page=1'; pages=0
while path:
    data=fetch(path); pages+=1
    for o in data['items']:
        oid=o['id']
        if oid in seen:
            seen[oid]['repeats'] += 1
        else:
            seen[oid]={'order':o,'repeats':0}
    path=data.get('next')
print('pages',pages,'unique',len(seen),'listings',sum(v['repeats']+1 for v in seen.values()),'duplicates',sum(v['repeats'] for v in seen.values()), flush=True)

cache={}
for v in seen.values():
    o=v['order']; cid=o['customer_id']
    if cid not in cache: cache[cid]=fetch('/customers/'+str(cid))

start=datetime(2025,3,1,tzinfo=timezone.utc); end=datetime(2025,6,1,tzinfo=timezone.utc)
by={r:0 for r in ('north','south','east','west')}; count=0
qual=[]
for v in seen.values():
    o=v['order']
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if o['status']=='shipped' and start <= dt < end:
        c=cache[o['customer_id']]; pct=c['discount_pct']
        cents=(Decimal(o['amount_cents'])*(Decimal(100-pct)/Decimal(100))).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        by[c['region']]+=int(cents); count+=1
        qual.append((o['id'],o['placed_at'],dt.isoformat(),o['amount_cents'],pct,int(cents),c['region']))
print('customers',len(cache),'qualifying',count,'by',by,'total',sum(by.values()), flush=True)
print('offset_placed',sum(1 for v in seen.values() if '+' in v['order']['placed_at'] or v['order']['placed_at'].endswith('Z')==False), 'qual_offset',sum(1 for q in qual if '+' in q[1][10:]), flush=True)
print('status_counts', {s:sum(1 for v in seen.values() if v['order']['status']==s) for s in ('placed','shipped','cancelled','returned')}, flush=True)
print(json.dumps({'total_cents':sum(by.values()),'order_count':count,'duplicates_skipped':sum(v['repeats'] for v in seen.values()),'by_region':by}, sort_keys=True))
PY"

